html:
{{ get_solua_print_css() }}{% set p = get_pick_list_print_data(doc) %}
<h2>Pick List / 拣货单</h2>
{% if doc.docstatus != 1 %}<div class="warning">{{ 'RASCUNHO / 草稿' if doc.docstatus == 0 else 'CANCELADO / 已取消' }} — Documento não oficial / 非正式凭证</div>{% endif %}
<table class="meta"><tr><td><b>{{ p.company | e }}</b><br>N.º / 编号: {{ doc.name | e }}<br>Uso / 用途: {{ p.purpose | e }}<br>Origem / 来源: {{ p.source or '—' | e }}</td><td><b>Cliente / 客户: {{ p.customer or '—' | e }}</b><br>Data / 日期: {{ doc.get('creation') and doc.get('creation')[:10] or '' }}<br>Status / 状态: {{ doc.get('status') or '' | e }}</td></tr></table>
<table class="items"><thead><tr><th>#</th><th>Foto / 图片</th><th>Artigo / 商品</th><th class="col-sku">SKU / 货号</th><th>Código de cor / 色号</th><th class="col-barcode">条码 / Código de barras</th><th class="col-description">描述 / Descrição</th><th class="col-qty">Quantidade /<br>数量</th><th>Separado / 已拣</th><th class="col-uom">Un.</th><th>Armazém / 仓库</th><th>S.O.</th></tr></thead><tbody>
{% for item in p['items'] %}<tr><td>{{ loop.index }}</td><td>{% if item.image %}<img class="photo" src="{{ item.image | e }}">{% endif %}</td><td>{{ item.item_name | e }}</td><td>{{ item.item_code | e }}</td><td>{{ (item.color_code or '—') | e }}{% if item.color %}<br>{{ item.color | e }}{% endif %}</td><td class="col-barcode">{{ (item.barcode or '—') | e }}</td><td>{{ (item.description or '—') | e }}</td><td class="num">{{ format_print_qty(item.qty) }}</td><td class="num">{{ format_print_qty(item.picked_qty) }}</td><td class="col-uom">{{ item.uom | e }}</td><td>{{ item.warehouse | e }}</td><td>{{ item.sales_order | e }}</td></tr>{% endfor %}
</tbody><tfoot><tr><td colspan="7" class="num"><b>Total Qty / 总数量</b></td><td class="num"><b>{{ format_print_qty(p.total_qty) }}</b></td><td class="num"><b>{{ format_print_qty(p.total_picked) }}</b></td><td colspan="3"></td></tr></tfoot></table>
<div class="block sign">Separado por / 拣货人: ____________________　Verificado por / 核对: ____________________　日期 / Data: ____________________</div>
<div id="footer-html" class="visible-pdf"><div class="text-center">{{ doc.name | e }} · <span class="page"></span> / <span class="topage"></span></div></div>
